action.code:
inputs = ['vxg', 'kfyzcy', 'xed', 'uz', 'gk']
outputs = ['ag', 'kfyzcy', 'cjbed', 'vz', 'gk']

# Let me check each character position carefully
print("Position-by-position analysis:")
print("=" * 30)

for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{out}'")
    min_len = min(len(inp), len(out))

    # Check positions where characters differ
    diff_positions = []
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_positions.append((j, inp[j], out[j]))

    if len(inp) != len(out):
        if len(inp) > len(out):
            print(f"  Removed chars from position {min_len}: '{inp[min_len:]}'")
        else:
            print(f"  Added chars at position {min_len}: '{out[min_len:]}'")

    if diff_positions:
        for pos, old_char, new_char in diff_positions:
            print(f"  Position {pos}: '{old_char}' -> '{new_char}'")
    else:
        print("  No character differences")

# Now let me look at possible replacements
print("\n\nLooking for replacement patterns:")
print("=" * 30)

# Check if there are common substrings that might be replaced
all_chars = set()
for inp in inputs:
    all_chars.update(inp)
for out in outputs:
    all_chars.update(out)

print("All unique characters:", sorted(all_chars))

# Let me focus on what happens to each character in context
print("\nCharacter replacement analysis:")
for char in sorted(all_chars):
    print(f"\nCharacter '{char}':")
    found_instances = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if char in inp:
            pos = inp.find(char)
            found_instances.append((i, inp, pos))
    if found_instances:
        for i, inp, pos in found_instances:
            print(f"  In '{inp}' at position {pos}")

